CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,nick TEXT NOT NULL UNIQUE COLLATE NOCASE,pw TEXT NOT NULL,salt TEXT NOT NULL,plays INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,uid INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS best(uid INTEGER NOT NULL,unit INTEGER NOT NULL,score INTEGER NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(uid,unit));
CREATE TABLE IF NOT EXISTS wrong(uid INTEGER NOT NULL,word TEXT NOT NULL,cnt INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(uid,word));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,unit INTEGER NOT NULL DEFAULT 0,text TEXT NOT NULL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ix_c_at ON comments(at);
CREATE INDEX IF NOT EXISTS ix_b_unit ON best(unit,score);
CREATE TABLE IF NOT EXISTS attendance(uid INTEGER NOT NULL,day TEXT NOT NULL,at INTEGER NOT NULL,streak INTEGER NOT NULL DEFAULT 1,msg TEXT NOT NULL DEFAULT '',PRIMARY KEY(uid,day));
CREATE INDEX IF NOT EXISTS ix_a_day ON attendance(day,at);
CREATE TABLE IF NOT EXISTS study(uid INTEGER NOT NULL,word TEXT NOT NULL,known INTEGER NOT NULL DEFAULT 0,star INTEGER NOT NULL DEFAULT 0,at INTEGER NOT NULL,PRIMARY KEY(uid,word));
